window.FILM_WORK_PROMPTS={"work_id":"src-35939344e9e47362","records":[{"work_id":"src-35939344e9e47362","frame_id":"FG-e819b09e21064fcc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1094).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"画面主体为幽暗森林中的林间空地，地面散落着稀疏的枯枝与倒木，背景是几根垂直挺立的细长树干，整体环境极度昏暗，几乎被黑色吞没。","analysis":"构图呈现大面积暗部，视觉重心位于画面右下方的微弱亮区。画面中无清晰人物主体，仅见环境细节。视角平视，光线极弱，呈现冷调青蓝色，明暗对比极低，细节隐没在阴影中，营造出压抑、静谧且神秘的视觉氛围。","prompt":"这是一幅极度昏暗的森林夜景画面，整体色调为深沉的冷青色与黑色。画面大部分区域被浓重的阴影覆盖，细节难以辨认。在画面右下方，隐约可见一片林间空地，地面上横七竖八地散落着几根细长的枯木或树枝，呈现出灰暗的轮廓。背景深处矗立着几根垂直的细长树干，在黑暗中若隐若现。光线极其微弱，仿佛来自极远处的冷光源，使得画面呈现出一种压抑、静谧且略带诡异的氛围，没有任何明显的人物或动物活动迹象。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:10:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1094).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.276,"observed_resolution":"normal","observation_limits":[],"id":"VP-4324b261a07c6042","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-11d8c795da27c909","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1117).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"画面主体为一名年轻女性的右侧面部特写，她面朝右侧，嘴唇微张。背景为极度虚化的户外环境，可见模糊的灰褐色地面与暗色阴影，环境占比约三分之一。","analysis":"构图采用极近距离的侧面特写，人物面部占据画面左侧及中央大部分区域，右侧留白给虚化背景。可见范围仅限头部侧面，包括发丝、眉眼、鼻梁、嘴唇及下巴。光线从右前方照射，形成强烈的明暗对比，面部受光面呈现暖金色调，发丝边缘有高光，背景处于暗部且失焦。","prompt":"极近距离的侧面特写，展示一名年轻女性的右侧面部轮廓。她面朝右侧，嘴唇微张，神情平静。强烈的暖色侧光从右前方照射，照亮了鼻梁、脸颊和下巴，使皮肤呈现细腻的金色质感，发丝边缘被光线勾勒出明亮的轮廓。背景完全虚化，呈现出模糊的灰褐色地面与暗色阴影，营造出浅景深效果。画面色彩对比强烈，明暗分明，聚焦于人物面部的立体感与光影细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:10:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1117).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.387,"observed_resolution":"normal","observation_limits":[],"id":"VP-6a1a86c084858312","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-c5f5252da3552f5a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1114).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"画面主体为一片开阔的荒野，前景是枯黄的草地，中景分布着稀疏的针叶树，背景是茂密的针阔混交林，上方占据约三分之一画面的厚重云层。","analysis":"构图采用横向展开，地平线位于画面下方约三分之一处。前景草地呈现大面积的枯黄色，中景树木呈深绿色，背景森林颜色更深。光线为阴天漫射光，整体色调偏冷且饱和度较低，云层厚重，明暗对比不强烈，营造出一种静谧、荒凉且略带压抑的视觉氛围。","prompt":"这是一幅横向构图的荒野风景画面。前景是大片枯黄的草地，色调呈暗褐色，草地上零星散布着几棵矮小的针叶树。中景是一片茂密的树林，由深绿色的针叶树和颜色稍浅的阔叶树混合组成，树冠轮廓清晰。背景是连绵的森林，颜色较深。画面上方约三分之一被厚重的灰白色云层占据，云层层次丰富，光线柔和且均匀，没有强烈的直射阳光。整体色彩饱和度较低，呈现出一种阴郁、静谧且略带荒凉的自然氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:10:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1114).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.472,"observed_resolution":"normal","observation_limits":[],"id":"VP-3379f0c9b14a870c","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-9178e194627944db","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1092).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"蓝天背景下，大量红、黄、蓝、绿、白等彩色长条状彩带从画面左上方呈放射状向右下方密集垂落，线条交错重叠，占据绝大部分视野，左下方隐约可见白色金属塔架结构。","analysis":"画面采用仰视视角，主体为无数条色彩鲜艳的细长彩带，呈对角线构图贯穿画面。彩带线条流畅且密集，形成强烈的视觉引导线。背景为纯净的浅蓝色天空，光线明亮均匀，色彩饱和度高，红黄蓝绿白各色交织，无阴影遮挡，整体呈现出一种动态的、轻盈的视觉质感。","prompt":"仰视视角，蓝天背景下，大量红、黄、蓝、绿、白等彩色长条状彩带从画面左上方呈放射状向右下方密集垂落，线条交错重叠，占据绝大部分视野，左下方隐约可见白色金属塔架结构，光线明亮均匀，色彩饱和度高，红黄蓝绿白各色交织，无阴影遮挡，整体呈现出一种动态的、轻盈的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:10:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1092).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.853,"observed_resolution":"normal","observation_limits":[],"id":"VP-f72449022ce26fb8","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-f135a1ebc3226236","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (999).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"昏暗病房内，一名赤裸上身的男子仰卧在病床上，身上盖着深绿色被单，床头旁放置着金属推车，背景是透着冷光的垂直百叶窗。","analysis":"画面采用平视视角，主体人物占据画面左下至中部区域，呈现仰卧姿态。人物上半身裸露，下半身被深绿色被单覆盖，头部枕在白色枕头上。背景大面积的垂直百叶窗占据右上方，透出冷蓝色光线，与前景的暗部形成对比。左侧墙面为深蓝色，整体色调偏冷，光影层次分明，营造出静谧且略带压抑的氛围。","prompt":"昏暗的医院病房场景，一名男子仰卧在病床上，头部枕着白色枕头，上半身赤裸，下半身盖着深绿色的厚重被单。床头左侧悬挂着输液装置，旁边有一张金属推车，上面摆放着药瓶和医疗用品。背景是大面积的垂直百叶窗，透出冷蓝色的自然光，照亮了房间的一侧。左侧墙面呈现深蓝色调，整体光线昏暗，色彩以冷蓝和深绿为主，营造出一种安静、阴冷的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:10:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (999).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.502,"observed_resolution":"normal","observation_limits":[],"id":"VP-8003e9a46fcf3f5c","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-c5b7cbac296e3370","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1094).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"巨大的灰白色岩石洞穴入口，内部漆黑深邃。一名身穿深色衣物的人物独自站立在洞口边缘，周围是粗糙的岩壁与碎石地面。","analysis":"画面采用广角视野，巨大的岩石结构占据绝大部分空间，形成强烈的压迫感。人物位于画面左侧中景，全身可见，身形在巨大的岩洞前显得极其渺小。光线从外部自然射入，照亮了前景的岩石表面，而洞穴内部则陷入完全的黑暗，形成了极端的明暗对比。","prompt":"这是一张写实风格的户外场景图。画面主体是一个巨大的天然岩石洞穴，岩壁呈现出灰白色的层状纹理，表面粗糙且布满风化痕迹。洞穴内部是一片深邃的漆黑，与外部明亮的岩石形成强烈反差。在洞穴入口的左侧边缘，站立着一个身穿深色无袖上衣和深色长裤的人物，其身形在巨大的岩石背景下显得非常渺小。前景是大片起伏的灰白色岩石地面，右侧边缘生长着少许稀疏的绿色植被。整体光线为自然散射光，色调偏冷，营造出一种荒凉、静谧且略带神秘感的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:36:54+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1094).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-6bd93954011642b0","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-1385ff4da92caded","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1117).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"黄昏时分的乡村全景，太阳正落入远处茂密的森林线后，前景是起伏的草地、零散树木与一处房屋，天空呈现橙黄色调。","analysis":"画面采用高角度俯视构图，环境占比极大。太阳位于画面中央偏上，被树梢遮挡形成强烈的逆光剪影效果。前景草地与树木在背光下呈现深暗色调，仅保留轮廓。天空占据上半部分，色彩从地平线的亮橙过渡到顶部的淡黄，云层稀薄。整体明暗对比强烈，营造出静谧的黄昏氛围。","prompt":"黄昏时分的乡村全景，太阳正落入远处茂密的森林线后，发出耀眼的橙红色光芒。前景是起伏的草地，散布着零星的树木和灌木，中央偏右有一处房屋建筑。天空呈现从亮橙到淡黄的渐变色，云层稀薄。画面采用高角度俯视构图，环境占比极大，前景草地与树木在背光下呈现深暗色调，仅保留轮廓。整体明暗对比强烈，营造出静谧的黄昏氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:37:01+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1117).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.518,"observed_resolution":"normal","observation_limits":[],"id":"VP-d0f10dd9100bcf31","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-233ca869d6954280","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1114).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"夜晚街道，一名男子背对镜头站立，右肩搭着浅色衣物，左侧有黄黑条纹立柱，背景是模糊的灯光与建筑轮廓。","analysis":"人物位于画面右侧，仅可见上半身背影，头部微侧向左。左侧前景竖立一根黄黑相间的警示柱，占据画面左下部分。背景处于焦外，散布着多组白色圆形光斑和右侧一处红色亮区。整体色调偏暗，以黑色和深褐色为主，光源呈现暖黄与冷白对比，明暗反差强烈。","prompt":"夜晚城市街道，一名男子背对镜头站立于画面右侧，身穿深色外套，右肩随意搭着一件浅色衣物，头发灰白。左侧前景有一根黄黑条纹相间的立柱，立于浅色基座上。背景虚化，远处可见多组白色圆形路灯光斑，右侧背景有一处模糊的红色发光区域。画面整体昏暗，以黑色和深褐色为主调，灯光呈现暖黄与冷白交织，明暗对比强烈，营造出静谧的夜间氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:37:08+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1114).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.328,"observed_resolution":"normal","observation_limits":[],"id":"VP-3939f49ed7f74670","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-e1443d8771dbafa2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1085).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"一名长发人物面部占据画面中心，神情凝重。背景为极度虚化的夜间城市环境，散布着蓝色、黄色和白色的模糊光斑。","analysis":"画面采用中心构图，人物面部特写占据主要视觉空间，仅可见头部及颈部上方。背景完全失焦，形成强烈的虚实对比。光线昏暗，人物面部处于阴影中，仅靠环境光微弱照亮。背景光斑色彩丰富，左侧偏冷蓝，右侧偏暖黄，营造出夜晚都市的氛围。","prompt":"一张夜间人物面部特写照片。画面中心是一名留着长直发的人物，面部大部分处于阴影中，神情严肃且略显疲惫，眼神直视前方。人物穿着灰色高领衣物，仅露出头部和颈部。背景是极度模糊的城市夜景，由无数失焦的光斑组成，左侧主要是冷色调的蓝色和白色光点，右侧则是暖色调的黄色和橙色光块，营造出一种孤独、忧郁的都市夜晚氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:37:15+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (1085).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-668a7850e790ca05","origin":"visual"},{"work_id":"src-35939344e9e47362","frame_id":"FG-54808f9b5cb5b7d2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (987).jpg","source_page":"https://film-grab.com/2014/09/23/the-intruder/","scene":"两名身穿白色衣物的人物位于画面中后景，前景被一排垂直的白色栅栏遮挡，背景为深蓝色墙面，整体氛围幽暗冷峻。","analysis":"构图上，前景的垂直白色栅栏占据画面大部分宽度，形成强烈的视觉分割。两名人物位于栅栏后方，仅上半身及头部可见，右侧人物面部轮廓较清晰，左侧人物稍显模糊。光线昏暗，主要光源似乎来自前方或上方，在人物面部和白色衣物上形成微弱的高光，与深蓝色背景形成冷暖对比。","prompt":"这是一张冷色调的静帧画面，整体笼罩在深蓝色的环境光中。前景是一排垂直排列的白色栅栏，栅栏条粗细均匀，间距适中，占据了画面的大部分前景空间，形成一种窥视或阻隔的视觉效果。在栅栏后方，有两名身穿白色宽松衣物的人物。右侧的人物面部轮廓较为清晰，头发向后梳理，神情平静，目光似乎看向侧方；左侧的人物位置稍低且模糊，仅能看到头部和肩部的轮廓。背景是纯净的深蓝色，没有多余的细节，突出了前景的栅栏和后方的人物。光线柔和而阴冷，在人物面部和白色衣物上投下淡淡的阴影，营造出一种神秘、压抑且静谧的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:37:23+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (987).jpg","observed_dimensions":[1017,432],"source_thumbnail_dimensions":[500,212],"source_image_match_mae":0.513,"observed_resolution":"normal","observation_limits":[],"id":"VP-43f0f3e19bc0459a","origin":"visual"}]};